D={
920045:("ago / last / next / in","**Ago** e **last** falam do passado; **next** fala do futuro; **in** vai com meses e anos.",[("I came two years {{ago}}.","Cheguei há dois anos."),("{{Last}} week I visited Paris.","Na semana passada visitei Paris."),("{{Next}} week I will go home.","Na semana que vem vou para casa."),("I'll travel {{in}} July.","Vou viajar em julho.")],"Qual aponta para o futuro?",["last week","two years ago","next week"],2,"Next = próximo."),
81316:("I promise","Prometer: **I promise I will + verbo**. Desculpas: **I'm sorry. Please forgive me.**",[("{{I promise}} I will listen.","Prometo que vou ouvir."),("{{I want to apologize}}.","Quero pedir desculpas."),("{{Please forgive me}}.","Por favor, me perdoe."),("I {{will never}} do it again.","Nunca mais farei isso.")],"“Forgive me” pede…",["perdão","dinheiro","tempo"],0,"Forgive = perdoar."),
81317:("will: futuro","Futuro: **will + verbo**; negativa: **won't**.",[("It {{will cost}} twenty dollars.","Vai custar vinte dólares."),("{{I'll fix}} it tomorrow.","Eu conserto amanhã."),("It {{won't take}} long.","Não vai demorar."),("{{Will it}} be ready today?","Ficará pronto hoje?")],"“It won't take long” quer dizer…",["Vai demorar muito.","Não vai demorar.","Já demorou."],1,"Won't = will not."),
81318:("must / mustn't","**Must** = obrigação; **mustn't** = proibido.",[("You {{must wear}} a seatbelt.","Você deve usar cinto."),("You {{mustn't drive}} too fast.","Você não deve dirigir rápido demais."),("The {{limit}} is sixty kilometers per hour.","O limite é sessenta quilômetros por hora."),("You {{must}} have a license.","Você deve ter carteira.")],"Qual é uma proibição?",["You must stop.","You mustn't park here.","You can park."],1,"Mustn't."),
81319:("Placas","Placas dão ordens (*Stop. Yield. Turn left.*) e proíbem (*No U-turn. You can't park here.*).",[("{{Stop}} at the sign.","Pare na placa."),("You {{can't turn left}} here.","Você não pode virar à esquerda aqui."),("{{Go straight}} on the highway.","Siga em frente na estrada."),("{{No U-turn}}.","Proibido retorno.")],"“Yield” significa…",["dê a preferência","acelere","estacione"],0,"Yield = dar a preferência."),
81320:("if + presente, will","Condições reais: **If + presente, will + verbo**.",[("{{If I practice}}, I'll pass.","Se eu praticar, passarei."),("{{If I don't practice}}, I'll fail.","Se eu não praticar, serei reprovado."),("What {{will happen}} if you fail?","O que acontece se você falhar?"),("If you study, you {{will}} succeed.","Se você estudar, terá sucesso.")],"Qual está certa?",["If I will practice, I pass.","If I practice, I'll pass.","If I practiced, I'll pass."],1,"If + presente."),
81321:("Have you ever…?","Experiências: **Have you ever + particípio?** Nunca: **I have never + particípio**.",[("{{Have you ever seen}} this episode?","Você já viu este episódio?"),("I {{have seen}} it three times.","Já vi três vezes."),("I {{have never eaten}} so much.","Nunca comi tanto."),("She {{has watched}} the whole series.","Ela assistiu à série toda.")],"Qual é o particípio de “eat”?",["ate","eaten","eated"],1,"Eat, ate, eaten."),
81322:("Can I / Could you","Pedir licença: **Can I…?** Educado: **Could you…?**",[("{{Can I share}} your photo?","Posso compartilhar sua foto?"),("{{Could you delete}} that post?","Você poderia apagar aquele post?"),("{{Think}} before you post.","Pense antes de postar."),("{{Could I}} tag you?","Posso marcar você?")],"Qual é mais educado?",["Delete it!","Could you delete it?","You delete."],1,"Could you…?"),
920046:("What a / How","**What a + substantivo**; **How + adjetivo**.",[("{{What a day}}!","Que dia!"),("{{How beautiful}} it is!","Que lindo!"),("{{What a}} great robot!","Que robô incrível!"),("{{How amazing}}!","Que incrível!")],"Qual está certa?",["What beautiful!","How beautiful!","What a beautiful!"],1,"How + adjetivo."),
81323:("going to","**Be going to + verbo** para planos.",[("I'm {{going to take}} a selfie.","Vou tirar uma selfie."),("We {{are going to pose}} together.","Vamos posar juntos."),("{{Are you ready}}?","Está pronto?"),("Everyone {{is going to}} smile.","Todo mundo vai sorrir.")],"Complete: “We ___ going to pose.”",["is","are","am"],1,"We: are."),
81324:("past continuous","**Was/were + verbo-ing** para algo em andamento no passado.",[("She {{was making}} a vase.","Ela estava fazendo um vaso."),("They {{were laughing}} all afternoon.","Eles riram a tarde toda."),("{{What were you doing}}?","O que você estava fazendo?"),("I {{was shaping}} the clay.","Eu estava modelando a argila.")],"Complete: “They ___ working.”",["was","were","is"],1,"They: were."),
81325:("How often","Frequência: **daily, weekly, monthly** ou **once / twice / three times a week**.",[("{{How often}} do you train?","Com que frequência você treina?"),("I train {{daily}}.","Treino diariamente."),("We have a {{weekly}} class.","Temos aula semanal."),("We fight {{twice a month}}.","Lutamos duas vezes por mês.")],"“Weekly” significa…",["todo dia","toda semana","todo mês"],1,"Weekly = semanal."),
81326:("look for / apply for","**Look for** = procurar; **apply for** = candidatar-se.",[("I'm {{looking for}} a job.","Estou procurando emprego."),("I want to {{apply for}} this job.","Quero me candidatar a esta vaga."),("{{Do you have}} any experience?","Você tem experiência?"),("They are {{looking for}} workers.","Estão procurando trabalhadores.")],"Complete: “I want to apply ___ the job.”",["to","for","at"],1,"Apply for."),
81327:("must have / be able to","Anúncios: **must have** (deve ter) e **be able to** (ser capaz de).",[("You {{must have}} a license.","Você deve ter carteira."),("You {{must be able to}} drive.","Você deve saber dirigir."),("The {{salary}} is good.","O salário é bom."),("You must {{apply}} online.","Você deve se candidatar on-line.")],"“Be able to” significa…",["ser capaz de","ser proibido","ser obrigado"],0,"Able = capaz."),
81328:("already / yet","**Already** (afirmativa); **yet** (negativa e pergunta).",[("I've {{already}} packed my suit.","Já arrumei meu terno."),("I haven't packed my tie {{yet}}.","Ainda não arrumei a gravata."),("Have you packed {{yet}}?","Você já arrumou?"),("She has {{already}} left.","Ela já saiu.")],"Complete: “I haven't called him ___.”",["already","yet","just"],1,"Negativa: yet."),
81329:("Can I have your…?","Pedir com educação: **Can I have your number? Can I have your email?**",[("{{Can I have}} your number?","Posso ter seu número?"),("{{What is}} your email?","Qual é o seu e-mail?"),("I'll {{send}} you a message.","Eu mando uma mensagem."),("{{Let's keep}} in touch.","Vamos manter contato.")],"Como pedir o e-mail?",["Can I have your email?","Give your email.","Your email I want."],0,"Can I have…?"),
920047:("how much / how many","**How much** com incontáveis; **how many** com contáveis.",[("{{How much}} sugar is there?","Quanto açúcar há?"),("{{How many}} eggs are there?","Quantos ovos há?"),("A cup {{of}} sugar.","Uma xícara de açúcar."),("Two {{tablespoons}} of oil.","Duas colheres de sopa de óleo.")],"Complete: “How ___ flour?”",["many","much","few"],1,"Farinha não se conta."),
81330:("Is it included?","O que vem junto: **Is … included?**",[("{{Is water included}}?","A água está incluída?"),("There {{is}} one bedroom.","Há um quarto."),("{{How much}} is the rent?","Quanto é o aluguel?"),("{{Is parking included}}?","O estacionamento está incluído?")],"Complete: “___ the internet included?”",["Is","Are","Does"],0,"Internet: is."),
81331:("have to / can't","Obrigação: **have to**; proibição: **can't**.",[("You {{have to}} sign here.","Você tem de assinar aqui."),("You {{can't have}} a pet.","Você não pode ter animal."),("{{Do I have to}} sign today?","Preciso assinar hoje?"),("You {{have to}} pay the deposit.","Você precisa pagar o depósito.")],"“You can't have a pet” quer dizer…",["Pode ter animal.","Não pode ter animal.","Deve ter animal."],1,"Can't = não pode."),
81332:("How much / How many","**How much** para incontáveis e preços; **how many** para contáveis.",[("{{How much}} is the water bill?","Quanto é a conta de água?"),("{{How many}} bills do we have?","Quantas contas temos?"),("It {{costs}} forty dollars.","Custa quarenta dólares."),("{{How much}} is the total?","Quanto é o total?")],"Complete: “How ___ bills?”",["much","many","long"],1,"Bills se contam."),
81333:("Superlativos","**The most + adjetivo longo** ou **the -est** em curtos.",[("It is {{the most popular}} food.","É a comida mais popular."),("This is {{the sweetest}} dessert.","Esta é a sobremesa mais doce."),("My favorite is {{feijoada}}.","Minha favorita é feijoada."),("That's {{the best}} dish.","Esse é o melhor prato.")],"Qual está certa?",["the most sweet","the sweetest","the sweeter"],1,"Sweet é curto: the sweetest."),
81334:("a little / a few","**A little** com incontáveis; **a few** com contáveis.",[("{{A little}} rice, please.","Um pouco de arroz, por favor."),("{{A few}} carrots, please.","Algumas cenouras, por favor."),("{{How much}} rice do you want?","Quanto arroz você quer?"),("A plate needs {{a little}} protein.","Um prato precisa de um pouco de proteína.")],"Complete: “a ___ grapes”",["little","few","much"],1,"Grapes se contam: a few."),
81335:("How much / How many","**How much** para preço; **how many** para quantidade contável.",[("{{Can I pay}} by card?","Posso pagar no cartão?"),("The bill is {{due}} on Friday.","A conta vence na sexta."),("{{How much}} is the bill?","Quanto é a conta?"),("{{How many}} bills do you have?","Quantas contas você tem?")],"“How much is it?” pergunta…",["o preço","a quantidade","o horário"],0,"How much = preço."),
81336:("-ing como sujeito","O verbo com **-ing** pode ser o sujeito: *Baking is fun.*",[("{{Baking}} is fun.","Assar é divertido."),("{{Cooking at home}} is cheap.","Cozinhar em casa é barato."),("I like {{baking}} cakes.","Gosto de assar bolos."),("{{Eating well}} is important.","Comer bem é importante.")],"Qual está certa?",["Bake is fun.","Baking is fun.","To baking is fun."],1,"Sujeito: verbo-ing."),
920048:("What do you do?","Profissão: **What do you do?** Resposta: **I work as…**",[("{{What do you do}} now?","O que você faz agora (profissão)?"),("I {{work as}} a nurse.","Trabalho como enfermeira."),("I'm in a {{full-time}} job.","Tenho um emprego de tempo integral."),("I have a lot of {{experience}}.","Tenho muita experiência.")],"Complete: “I work ___ a cook.”",["in","as","at"],1,"Função: as."),
81338:("May I","**May I** é um jeito educado de pedir permissão.",[("{{May I}} come in?","Posso entrar?"),("{{May I}} visit him?","Posso visitá-lo?"),("He is in room {{twelve}}.","Ele está no quarto doze."),("{{May I}} ask a question?","Posso fazer uma pergunta?")],"Qual é mais formal?",["Can I come in?","May I come in?","I come in?"],1,"May I."),
81339:("present perfect: progresso","Progresso: **have/has + particípio**.",[("I {{have done}} therapy for six weeks.","Faço terapia há seis semanas."),("He {{has improved}} a lot.","Ele melhorou muito."),("{{Have you exercised}} today?","Você se exercitou hoje?"),("My knee {{has gotten}} stronger.","Meu joelho ficou mais forte.")],"Complete: “She ___ improved.”",["have","has","is"],1,"She: has."),
81340:("if + presente, presente","Fatos e hábitos: **if + presente, presente**.",[("If you eat well, you {{stay}} healthy.","Se você come bem, fica saudável."),("If I am sick, I {{stay}} home.","Se estou doente, fico em casa."),("If it rains, I {{take}} an umbrella.","Se chove, levo guarda-chuva."),("If I feel tired, I {{rest}}.","Se me sinto cansado, descanso.")],"Qual está certa?",["If it rains, I will to take.","If it rains, I take an umbrella.","If it rained, I take."],1,"Presente nos dois lados."),
81342:("Passado: revisão","Passado simples (**-ed** ou irregular) e **used to** para hábitos antigos.",[("I {{visited}} my aunt yesterday.","Visitei minha tia ontem."),("I {{used to live}} in a small town.","Eu morava numa cidade pequena."),("{{Did you see}} the rainbow?","Você viu o arco-íris?"),("We {{went}} home late.","Fomos para casa tarde.")],"Qual está certa?",["Did you saw it?","Did you see it?","Do you saw it?"],1,"Did + verbo base."),
81343:("Futuro: revisão","**Will** para promessas e decisões na hora; **going to** para planos feitos.",[("{{I will call}} you tomorrow.","Ligo para você amanhã."),("{{I'm going to take}} a trip.","Vou fazer uma viagem."),("{{Will you call}} me?","Você me liga?"),("{{Maybe}} it will rain.","Talvez chova.")],"Qual mostra uma promessa?",["I will help you.","I helped you.","I help you."],0,"Will = promessa."),
920049:("You should try it","**You should** recomenda; **it was + adjetivo** avalia.",[("{{You should try}} the park.","Você deveria conhecer o parque."),("{{It was amazing}}, really.","Foi incrível, de verdade."),("{{It is worth}} a try.","Vale a pena tentar."),("It's a hidden {{gem}}.","É uma joia escondida.")],"“Worth a try” significa…",["vale a pena","não vale","é caro"],0,"Vale a pena."),
81344:("Modais: revisão","**Can** = habilidade; **must** = obrigação; **should** = conselho. Todos + verbo base.",[("{{I can}} swim well.","Sei nadar bem."),("{{You must}} follow the path.","Você deve seguir o caminho."),("{{You should}} ask for advice.","Você deveria pedir conselho."),("She {{can}} run fast.","Ela sabe correr rápido.")],"Qual é conselho?",["You must go.","You should rest.","You can go."],1,"Should."),
81345:("do / does / did","Use **do/does** no presente e **did** no passado, com o verbo base.",[("{{Do you like}} films?","Você gosta de filmes?"),("{{Does he make}} films?","Ele faz filmes?"),("{{Did you see}} the film?","Você viu o filme?"),("{{Why do}} you ask?","Por que você pergunta?")],"Complete: “___ she work here?”",["Do","Does","Did"],1,"She: does."),
81346:("Tudo junto","Numa conversa você mistura **presente, passado e futuro**.",[("I {{live}} in a small town.","Moro numa cidade pequena."),("I {{walked}} down the street.","Caminhei pela rua."),("I {{will call}} you tomorrow.","Ligo para você amanhã."),("We {{laughed}} together.","Rimos juntos.")],"Qual está no futuro?",["I walked.","I will call.","I live."],1,"Will + verbo."),
81347:("A2: desafio final","Hoje você mistura tudo: **presente, passado e futuro**.",[("I {{learn}} English every day.","Aprendo inglês todo dia."),("I {{learned}} a lot.","Aprendi muito."),("I {{will keep}} learning.","Vou continuar aprendendo."),("I'm {{proud}} of my progress.","Tenho orgulho do meu progresso.")],"Qual está no passado?",["I learn.","I learned.","I will learn."],1,"Learned."),
81348:("Palavras de pergunta","**What, where, when, why, who, how** abrem as perguntas.",[("{{What}} is your hobby?","Qual é o seu passatempo?"),("{{Where}} do you live?","Onde você mora?"),("{{Why}} do you like it?","Por que você gosta?"),("{{Who}} is your favorite actor?","Quem é seu ator favorito?")],"“Why” pergunta…",["o motivo","o lugar","o tempo"],0,"Why = por quê."),
81349:("Perguntas de continuação","Para manter a conversa: **Really? Can you tell me more? What about you?**",[("{{Really}}? That is interesting.","Verdade? Que interessante."),("{{Can you tell me more}}?","Pode me contar mais?"),("{{What about you}}?","E você?"),("That's {{wonderful}}!","Que maravilha!")],"Qual mantém a conversa?",["What about you?","Stop talking.","I am done."],0,"Devolve a pergunta."),
81350:("look forward to + -ing","**Look forward to + verbo-ing** = esperar com alegria.",[("I {{look forward to learning}} more.","Espero aprender mais."),("{{Congratulations}} on your graduation!","Parabéns pela formatura!"),("We {{look forward to seeing}} you.","Aguardamos ver você."),("The next step is {{B1}}.","O próximo passo é o B1.")],"Qual está certa?",["I look forward to see you.","I look forward to seeing you.","I look forward see you."],1,"To + -ing."),
920050:("Passado, futuro, can","**Passado**, **futuro** e **can** juntos mostram seu progresso.",[("{{Last year}} I could not write an email.","No ano passado eu não sabia escrever um e-mail."),("{{Next year}} I will study more.","Ano que vem estudarei mais."),("{{Now}} I can talk about an email.","Agora sei falar sobre um e-mail."),("I am {{proud}} of my progress.","Tenho orgulho do meu progresso.")],"Qual é sobre o futuro?",["Last year I tried.","Next year I will study.","Now I can read."],1,"Next year + will."),
}
